// https://ronikaufman.github.io
// https://twitter.com/KaufmanRoni

let n = 12, s = 36, margin = 2*s, d = s*3/4;
const N_FRAMES = 100;
let tilts = [], levels = [];

function setup() {
  createCanvas(n*s+2*margin, n*s+2*margin);
  strokeWeight(2);
  //// noLoop() removed for animation

  for (let i = 0; i < n; i++) {
    let x = margin + (i+1/2)*s;
    let levelLine = [];
    let tiltLine = [];
    for (let j = 0; j < n; j++) {
      let y = margin + (j+1/2)*s;
      levelLine.push(dist(x, y, width/2, height/2)/24);
      tiltLine.push(atan2(y-height/2, x-width/2));
    }
    levels.push(levelLine);
    tilts.push(tiltLine);
  }
}

function draw() {
  background(255);
  let t = TAU*(frameCount%N_FRAMES)/N_FRAMES + 100;
  render(t);
}

function render(t) {
  for (let i = 0; i < n; i++) {
    var x = margin + (i+1/2)*s;
    for (let j = 0; j < n; j++) {
      var y = margin + (j+1/2)*s;
      let theta = abs(t-levels[i][j])%TAU;
      if (theta < PI) theta = PI-theta;

      noStroke();
      fill(0);
      arc(x, y, d, d, tilts[i][j]-theta, tilts[i][j]+theta, CHORD);

      stroke(0);
      noFill();
      circle(x, y, d);
    }
  }
}
